double percentage(int obtained, int total) {
    if (total <= 0)
        throw "Total marks must be positive";
    if (obtained < 0 || obtained > total)
        throw obtained;                       // throws an int
    return obtained * 100.0 / total;
}

int main() {
    try {
        cout << percentage(450, 500) << "%" << endl;   // 90%
        cout << percentage(520, 500) << "%" << endl;   // throws
    }
    catch (const char* m) { cout << "Error: " << m << endl; }
    catch (int x)         { cout << "Invalid marks: " << x << endl; }
    return 0;
}

