#include <iostream>
#include <exception>
using namespace std;

class InsufficientBalance : public exception {
public:
    const char* what() const noexcept override {
        return "Insufficient balance in account";
    }
};

class Account {
    double balance;
public:
    Account(double b) : balance(b) {}
    void withdraw(double amt) {
        if (amt > balance) throw InsufficientBalance();
        balance -= amt;
        cout << "Withdrawn: " << amt << ", Left: " << balance << endl;
    }
};

int main() {
    Account acc(2000);
    try {
        acc.withdraw(500);
        acc.withdraw(5000);
    }
    catch (const exception& e) {      // base class catches derived
        cout << "Error: " << e.what() << endl;
    }
    return 0;
}

