#include <iostream>
#include <stdexcept>
using namespace std;

double calculate(double a, double b, char op) {
    switch (op) {
        case '+': return a + b;
        case '-': return a - b;
        case '*': return a * b;
        case '/':
            if (b == 0) throw runtime_error("Cannot divide by zero");
            return a / b;
        default:
            throw invalid_argument("Unknown operator");
    }
}

int main() {
    double a, b; char op;
    cout << "Enter expression (e.g. 8 / 2): ";
    cin >> a >> op >> b;
    try {
        cout << "Answer = " << calculate(a, b, op) << endl;
    }
    catch (const invalid_argument& e) { cout << "Input error: " << e.what()
<< endl; }
    catch (const runtime_error& e)    { cout << "Math error: "  << e.what()
<< endl; }
    return 0;
}

#include <iostream>
#include <limits>
#include <stdexcept>
using namespace std;

int readAge() {
    int age;
    cin >> age;
    if (cin.fail()) {
        cin.clear();                                          // reset fail state
        cin.ignore(numeric_limits<streamsize>::max(), '\n'); // discard bad input
        throw invalid_argument("Please type digits only");
    }
    if (age < 1 || age > 120) throw out_of_range("Age must be 1 to 120");
    return age;
}

int main() {
    while (true) {
        cout << "Enter your age: ";
        try {
            int a = readAge();
            cout << "Age saved: " << a << endl;
            break;                          // valid, leave loop
        }
        catch (const exception& e) {
            cout << "Error: " << e.what() << ". Try again." << endl;
        }
    }
    return 0;
}

#include <iostream>
#include <stdexcept>
using namespace std;

const int SIZE = 5;
int getMark(int marks[], int index) {
    if (index < 0 || index >= SIZE)
        throw out_of_range("Roll number " + to_string(index) + " does not exist");
    return marks[index];
}

int main() {
    int marks[SIZE] = {67, 88, 92, 75, 81};
    int idx;
    cout << "Enter index (0-4): ";
    cin >> idx;
    try {
        cout << "Marks = " << getMark(marks, idx) << endl;
    }
    catch (const out_of_range& e) {
        cout << e.what() << endl;
    }
    return 0;
}

#include <iostream>
#include <stdexcept>
#include <string>
using namespace std;

class InvalidMarks : public runtime_error {
public:
    InvalidMarks(int m)
        : runtime_error("Invalid marks entered: " + to_string(m)) {}
};

char grade(int m) {
    if (m < 0 || m > 100) throw InvalidMarks(m);
    if (m >= 90) return 'A';
    if (m >= 75) return 'B';
    if (m >= 60) return 'C';
    if (m >= 33) return 'D';
    return 'F';
}

int main() {
    int list[] = {95, 72, 105, 40};
    for (int m : list) {
        try {
            cout << m << " -> Grade " << grade(m) << endl;
        }
        catch (const InvalidMarks& e) {
            cout << e.what() << endl;
        }
    }
    return 0;
}

